#include <iostream>
#include <vector>
#include <deque>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<long long> p(n + 1, 0);
    for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];

    deque<int> dq;
    long long min_sub = 0;

    for (int r = 1; r <= n; r++) {
        int j = r - 1;
        while (!dq.empty() && p[dq.back()] <= p[j]) {
            dq.pop_back();
        }
        dq.push_back(j);

        while (!dq.empty() && dq.front() < r - k) {
            dq.pop_front();
        }

        long long sub_sum = p[r] - p[dq.front()];
        if (sub_sum < min_sub) {
            min_sub = sub_sum;
        }
    }

    cout << p[n] - min_sub << "\n";
    return 0;
}

