import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        long[] a = new long[n];
        int idx = 0;
        while (idx < n) {
            if (!st.hasMoreTokens()) {
                line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
                continue;
            }
            a[idx++] = Long.parseLong(st.nextToken());
        }

        long[] p = new long[n + 1];
        for (int i = 0; i < n; i++) {
            p[i + 1] = p[i] + a[i];
        }

        ArrayDeque<Integer> dq = new ArrayDeque<>();
        long minSub = 0;

        for (int r = 1; r <= n; r++) {
            int j = r - 1;
            while (!dq.isEmpty() && p[dq.peekLast()] <= p[j]) {
                dq.pollLast();
            }
            dq.addLast(j);

            while (!dq.isEmpty() && dq.peekFirst() < r - k) {
                dq.pollFirst();
            }

            long subSum = p[r] - p[dq.peekFirst()];
            if (subSum < minSub) {
                minSub = subSum;
            }
        }

        System.out.println(p[n] - minSub);
    }
}
